import { useMemo, useState } from "react";
import lookup from "../data/lookup";

const CATEGORIES = [
  "Blouse", "Shirt", "Tank Top", "Top", "Scarf", "jackets",
  "Trousers", "Pants", "Skirt", "Shorts", "Blazer", "Vest",
  "Dress", "Shawl", "Fabric", "Throw", "Handkerchief", "Bagcharm",
  "Accessory", "Shopping Bag", "Pouch", "Scrunchy", "Key Holder",
];

/**
 * useCalculator
 * Encapsulates all lookup and calculation logic per README_TEAM specs.
 */
export function useCalculator() {
  const [category, setCategory] = useState("");
  const [title, setTitle] = useState("");
  const [size, setSize] = useState("");
  const [quantity, setQuantity] = useState(1);
  const [result, setResult] = useState(null); // null | { status, ... }

  // Titles filtered by selected category
  const titles = useMemo(() => {
    if (!category) return [];
    const set = new Set(
      lookup
        .filter((r) => r.product_type === category)
        .map((r) => r.title)
    );
    return [...set].sort();
  }, [category]);

  // Sizes filtered by selected title
  const sizes = useMemo(() => {
    if (!title) return [];
    const set = new Set(
      lookup.filter((r) => r.title === title).map((r) => r.size)
    );
    return [...set].sort();
  }, [title]);

  function handleCategoryChange(newCategory) {
    setCategory(newCategory);
    setTitle("");
    setSize("");
    setResult(null);
  }

  function handleTitleChange(newTitle) {
    setTitle(newTitle);
    setSize("");
    setResult(null);
  }

  function handleSizeChange(newSize) {
    setSize(newSize);
    setResult(null);
  }

  function calculate() {
    if (!title || !size || quantity < 1) return;
    const row = lookup.find((r) => r.title === title && r.size === size);
    if (!row) { setResult({ status: "not_found" }); return; }

    const total = parseFloat((row.E_total_kg_co2e * quantity).toFixed(4));
    const avoided = row.pathway === "B"
      ? parseFloat((row.avoided_kg_co2e * quantity).toFixed(4))
      : 0;

    setResult({
      status: "ok",
      title: row.title, size: row.size, quantity,
      pathway: row.pathway, product_type: row.product_type,
      dye_type: row.dye_type, natural_dye: row.natural_dye,
      total_kg: total, avoided_kg: avoided,
      per_unit_kg: row.E_total_kg_co2e,
      breakdown: {
        transport: row.E_transport, electricity: row.E_electricity,
        water: row.E_water, tailoring: row.E_tailoring,
      },
    });
  }


  function reset() {
    setCategory("");
    setTitle("");
    setSize("");
    setQuantity(1);
    setResult(null);
  }

  return {
    categories: CATEGORIES,
    category, setCategory: handleCategoryChange,
    title, setTitle: handleTitleChange,
    size, setSize: handleSizeChange,
    quantity, setQuantity,
    titles, sizes, result, calculate, reset,
  };
}
